package buftest

import (
	"emon/port"
	"testing"
)

func TestPushAnswersTheNewLengthAndKeepsTheLowEightBits(emonT *testing.T) {
	var b *port.Buf = port.NewBuf()
	port.AssertEq(emonT, port.BufLen(b), 0, "empty")
	port.AssertEq(emonT, port.BufPush(b, 65), 1, "the first push answers 1")
	port.AssertEq(emonT, port.BufPush(b, 511), 2, "the second answers 2")
	port.AssertEq(emonT, port.BufPush(b, -1), 3, "and the third 3")
	port.AssertEq(emonT, port.BufPush(b, 128), 4, "a byte with the high bit")
	port.AssertEq(emonT, port.BufPush(b, 4660), 5, "0x1234 keeps 0x34")
	port.AssertEq(emonT, port.BufLen(b), 5, "five bytes")
	port.AssertEq(emonT, port.BufAt(b, 0), 65, "0 is 65")
	port.AssertEq(emonT, port.BufAt(b, 1), 255, "511 is 255")
	port.AssertEq(emonT, port.BufAt(b, 2), 255, "-1 is 255")
	port.AssertEq(emonT, port.BufAt(b, 3), 128, "128 reads back as 128, not -128")
	port.AssertEq(emonT, port.BufAt(b, 4), 52, "0x34")
}

func TestSetOverwritesOneByte(emonT *testing.T) {
	var b *port.Buf = port.NewBuf()
	port.BufPush(b, 1)
	port.BufPush(b, 2)
	port.BufPush(b, 3)
	port.BufSet(b, 1, 300)
	port.AssertEq(emonT, port.BufAt(b, 0), 1, "untouched")
	port.AssertEq(emonT, port.BufAt(b, 1), 44, "300 keeps 44")
	port.AssertEq(emonT, port.BufAt(b, 2), 3, "untouched")
	port.AssertEq(emonT, port.BufLen(b), 3, "the length did not change")
}

func TestTruncateGoesToALengthAndPushesResumeThere(emonT *testing.T) {
	var b *port.Buf = port.NewBuf()
	port.BufPush(b, 10)
	port.BufPush(b, 20)
	port.BufPush(b, 30)
	port.BufTruncate(b, 1)
	port.AssertEq(emonT, port.BufLen(b), 1, "one left")
	port.AssertEq(emonT, port.BufPush(b, 99), 2, "the next push answers 2")
	port.AssertEq(emonT, port.BufAt(b, 1), 99, "and lands at 1")
	port.BufTruncate(b, 0)
	port.AssertEq(emonT, port.BufLen(b), 0, "emptied")
	port.BufTruncate(b, 0)
	port.AssertEq(emonT, port.BufLen(b), 0, "emptying an empty one is allowed")
}

func TestAppendBlobCopiesASpan(emonT *testing.T) {
	var b *port.Buf = port.NewBuf()
	port.BufPush(b, 7)
	port.BufAppendBlob(b, port.HexBlob("00ff80aa55"), 1, 4)
	port.AssertEq(emonT, port.BufLen(b), 4, "one and three")
	port.AssertEq(emonT, port.BufAt(b, 0), 7, "the first byte")
	port.AssertEq(emonT, port.BufAt(b, 1), 255, "ff")
	port.AssertEq(emonT, port.BufAt(b, 2), 128, "80")
	port.AssertEq(emonT, port.BufAt(b, 3), 170, "aa")
	port.BufAppendBlob(b, port.HexBlob("0102"), 0, 0)
	port.AssertEq(emonT, port.BufLen(b), 4, "an empty span appends nothing")
}

func TestItGrowsPastItsFirstAllocation(emonT *testing.T) {
	var b *port.Buf = port.NewBuf()
	var i int32 = 0
	for i < 100000 {
		port.BufPush(b, i)
		i += 1
	}
	port.AssertEq(emonT, port.BufLen(b), 100000, "100,000 bytes")
	port.AssertEq(emonT, port.BufAt(b, 0), 0, "first")
	port.AssertEq(emonT, port.BufAt(b, 255), 255, "255")
	port.AssertEq(emonT, port.BufAt(b, 256), 0, "wraps: 256 is 0")
	port.AssertEq(emonT, port.BufAt(b, 99999), 159, "99999 is 0x9F")
}

func TestBlobLendsTheContents(emonT *testing.T) {
	var b *port.Buf = port.NewBuf()
	port.BufPush(b, 1)
	port.BufPush(b, 255)
	port.BufPush(b, 128)
	port.AssertEq(emonT, port.BlobLen(port.BufBlob(b)), 3, "three bytes")
	port.AssertEq(emonT, port.BlobU8(port.BufBlob(b), 0), 1, "1")
	port.AssertEq(emonT, port.BlobU8(port.BufBlob(b), 1), 255, "255")
	port.AssertEq(emonT, port.BlobU8(port.BufBlob(b), 2), 128, "128")
	port.BufPush(b, 5)
	port.AssertEq(emonT, port.BlobLen(port.BufBlob(b)), 4, "a borrow taken after a write sees it")
}
